#!/usr/bin/env node
// scripts/build-superscript-xsl.mjs
//
// Reproducibly generates data/IEEE2006SuperscriptOfficeOnline.xsl from Word's
// IEEE2006OfficeOnline.xsl by wrapping the CITATION template's <body> in <sup>,
// so live Word citations render as superscript [N].
//
// Why a script (hostile-audit BUG 9): the XSL was originally generated by a
// one-off string-replace that targeted the FIRST <body> — which lives in the
// BIBLIOGRAPHY template, not the Citation template. The committed artifact was
// correct (someone manually targeted the right one), but the process was
// undocumented and fragile. This script targets the Citation template
// specifically and asserts there is exactly one <body> inside it.
//
// Usage:
//   node scripts/build-superscript-xsl.mjs            # reads %APPDATA%/.../IEEE, writes data/
//   node scripts/build-superscript-xsl.mjs <in.xsl>   # explicit input
//
// Run after a Word update replaces IEEE2006OfficeOnline.xsl.

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import os from "node:os";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");
const OUT = join(REPO_ROOT, "data", "IEEE2006SuperscriptOfficeOnline.xsl");
const VER = "<!-- pi-paper-lab superscript bibliography XSL v1 | generated from IEEE2006OfficeOnline.xsl | wraps the Citation template body in <sup> | see scripts/build-superscript-xsl.mjs -->";

function defaultInput() {
  if (process.platform !== "win32") return null;
  const appdata = process.env.APPDATA;
  if (!appdata) return null;
  return join(appdata, "Microsoft", "Bibliography", "Style", "IEEE2006OfficeOnline.xsl");
}

const inPath = process.argv[2] ?? defaultInput();
if (!inPath || !existsSync(inPath)) {
  console.error("Input IEEE XSL not found. Pass it explicitly:");
  console.error("  node scripts/build-superscript-xsl.mjs <path-to-IEEE2006OfficeOnline.xsl>");
  console.error("Default looked at:", inPath ?? "(non-Windows, no APPDATA)");
  process.exit(1);
}

let xsl = readFileSync(inPath, "utf-8");

// 1. Locate the Citation template (NOT the Bibliography template).
const startTag = '<xsl:template name="Citation">';
const i = xsl.indexOf(startTag);
if (i === -1) { console.error("Citation template not found in input XSL"); process.exit(1); }
const j = xsl.indexOf("</xsl:template>", i);
if (j === -1) { console.error("Citation template not closed in input XSL"); process.exit(1); }
const block = xsl.slice(i, j);
const nBody = block.split("<body>").length - 1;
const nClose = block.split("</body>").length - 1;
if (nBody !== 1 || nClose !== 1) {
  console.error(`Citation template has ${nBody} <body> / ${nClose} </body> — expected exactly 1 each. Aborting (Word may have changed the XSL structure).`);
  process.exit(1);
}

// 2. Wrap the single <body>...</body> in <sup>.
const block2 = block.replace("<body>", "<body><xsl:element name=\"sup\">", 1)
                    .replace("</body>", "</xsl:element></body>", 1);
xsl = xsl.slice(0, i) + block2 + xsl.slice(j);

// 3. Relabel the English (Lcid 1033) style name so Word lists it distinctly.
// Use a regex so CRLF (\r\n) and LF (\n) line endings both match.
const nameRe = /(<xsl:when test="b:StyleNameLocalized\/b:Lcid='1033'">\r?\n\s*)(<xsl:text>)IEEE(<\/xsl:text>)/;
if (!nameRe.test(xsl)) {
  console.error("Could not find the English IEEE style-name branch to relabel. Aborting.");
  process.exit(1);
}
xsl = xsl.replace(nameRe, "$1$2IEEE Superscript$3");

// 4. Prepend the version marker (replace any existing one).
xsl = xsl.replace(/<!-- pi-paper-lab superscript bibliography XSL v[0-9]+[^>]*-->\n?/, "");
const nl = xsl.indexOf("\n");
xsl = xsl.slice(0, nl + 1) + VER + "\n" + xsl.slice(nl + 1);

writeFileSync(OUT, xsl, "utf-8");
console.log(`Wrote ${OUT} (${xsl.length} bytes)`);
console.log("  - Citation template <body> wrapped in <sup>:", block2.includes('<xsl:element name="sup">'));
console.log("  - English style name:", xsl.includes("IEEE Superscript"));
console.log("  - version marker:", xsl.includes("pi-paper-lab superscript bibliography XSL v1"));
